package com.learn.hub.remote;

import java.util.List;

import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.cloud.openfeign.FallbackFactory;
import org.springframework.stereotype.Component;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** 声明式调用：地址来自注册中心，而不是写死在配置里。 */
@FeignClient(name = "topic-service", fallbackFactory = TopicClientFallback.class)
public interface TopicClient {

    @GetMapping("/api/v1/topics")
    List<TopicSummary> list(@RequestParam("q") String q);

    @GetMapping("/api/v1/topics/{slug}")
    TopicDetail get(@PathVariable("slug") String slug);
}

/** 兜底要能区分「可降级」与「必须报错」，否则等于把故障藏起来。 */
@Component
class TopicClientFallback implements FallbackFactory<TopicClient> {

    @Override
    public TopicClient create(Throwable cause) {
        return new TopicClient() {
            @Override
            public List<TopicSummary> list(String q) {
                return List.of();
            }

            @Override
            public TopicDetail get(String slug) {
                throw new TopicUnavailableException(slug, cause);
            }
        };
    }
}
